:host {
  display: block;
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
  text-align: center;
}

.seat-limit-info {
  margin: 0 auto 16px;
}

.auditorium {
  display: inline-block;
}

.screen-indicator {
  background: #444;
  color: white;
  text-align: center;
  letter-spacing: 4px;
  padding: 8px 0;
  margin-bottom: 16px;
  border-radius: 4px;
