  color: white;
  padding: 0;
  cursor: pointer;
}

.seat.unavailable,
.couch.unavailable {
  cursor: not-allowed;
}

.seat.available,
.couch.available {
  background-color: #2e7d32;
}

.seat.selected,
.couch.selected {
  background-color: #f9a825;
}

.seat.unavailable,
.couch.unavailable {
  background-color: #c62828;
}

.seat.accessible {
  background-color: #1565c0;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 24px;
