  gap: 8px;
}

.swatch {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 2px;
}

.selected-seats {
  margin-bottom: 24px;
}

.actions {
  display: flex;
  justify-content: center;
  gap: 16px;
}

