    cardCount: document.querySelectorAll('[data-testid="movie-card"]').length,
    loadingGone: !document.querySelector('[data-testid="movies-loading"]'),
  })`);
  console.log('cardsInfo', cardsInfo);

  // Pick a date with known screenings: 2026-09-15
  await navigate('http://localhost:4200/?date=2026-09-15');
  await waitFor(`document.querySelectorAll('[data-testid="movie-card"]').length > 0 || document.querySelector('[data-testid="movies-empty"]')`);
  await sleep(300);
  const sept15 = await evalJs(`JSON.stringify({
    cardCount: document.querySelectorAll('[data-testid="movie-card"]').length,
    screeningButtons: [...document.querySelectorAll('[data-testid="screening-button"]')].map(b => b.getAttribute('data-screening-id')),
  })`);
  console.log('sept15', sept15);
  const s15 = JSON.parse(sept15);
  check('sept15 has movie cards', s15.cardCount > 0, s15.cardCount);

  // Navigate directly to seat map for screening 1 (occupiedSeats known)
  await navigate('http://localhost:4200/screenings/1/seats');
  await waitFor(`document.querySelector('[data-testid="seat-map"]') !== null`);
  await sleep(300);

  const seatInfo = await evalJs(`JSON.stringify({
    title: document.querySelector('[data-testid="seat-map-title"]')?.textContent,
    subtitle: document.querySelector('[data-testid="seat-map-subtitle"]')?.textContent,
    seatCount: document.querySelectorAll('[data-testid="seat"]').length,
    couchCount: document.querySelectorAll('[data-testid="couch"]').length,
    unavailableSeats: document.querySelectorAll('[data-testid="seat"][data-state="unavailable"]').length,
    unavailableCouches: document.querySelectorAll('[data-testid="couch"][data-state="unavailable"]').length,
    accessibleSeats: document.querySelectorAll('[data-testid="seat"][data-state="accessible"]').length,
    aisles: document.querySelectorAll('[data-testid="aisle"]').length,
    rowLabelsLeft: document.querySelectorAll('[data-testid="row-label-left"]').length,
    rowLabelsRight: document.querySelectorAll('[data-testid="row-label-right"]').length,
    legendItems: [...document.querySelectorAll('[data-testid="legend-item"]')].map(i => i.getAttribute('data-state')),
    selectedCountText: document.querySelector('[data-testid="selected-seats-count"]')?.textContent,
    continueDisabled: document.querySelector('[data-testid="continue-button"]')?.disabled,
  })`);
  console.log('seatInfo', seatInfo);
  const si = JSON.parse(seatInfo);
  check('seat count 296', si.seatCount === 296, si.seatCount);
  check('couch count 12', si.couchCount === 12, si.couchCount);
  check('total 308', si.seatCount + si.couchCount === 308);
  check('accessible seats 6', si.accessibleSeats === 6, si.accessibleSeats);
  check('aisles 30 (2 per row x 15)', si.aisles === 30, si.aisles);
  check('row labels left 15', si.rowLabelsLeft === 15, si.rowLabelsLeft);
  check('row labels right 15', si.rowLabelsRight === 15, si.rowLabelsRight);
  check('legend 4 items', si.legendItems.length === 4, si.legendItems);
  check('title correct', si.title?.trim() === 'Choose your seats', si.title);
  check('subtitle has Show Date', si.subtitle?.includes('Show Date:'), si.subtitle);
  check('selected count 0 initially', si.selectedCountText?.trim() === 'Selected seats: 0', si.selectedCountText);
  check('continue disabled with no selection', si.continueDisabled === true, si.continueDisabled);
  // screening 1 occupiedSeats: R3C7,R3C8,R3C9,R6C12,R6C13,R11C21,R11C22,R15C5,R15C6 -> 7 single unavailable seats + 1 unavailable couch(5-6)
  check('unavailable seats = 7', si.unavailableSeats === 7, si.unavailableSeats);
  check('unavailable couches = 1', si.unavailableCouches === 1, si.unavailableCouches);

  // Select an available regular seat row 7 col 11, and the couch 1-2 on row 15
  const clickResult = await evalJs(`(() => {
    const seat = document.querySelector('[data-testid="seat"][data-row="7"][data-column="11"]');
    seat.click();
    return seat.getAttribute('data-state');
  })()`);
  console.log('clickResult seat7-11', clickResult);
  await sleep(200);

  const couchClick = await evalJs(`(() => {
    const couch = document.querySelector('[data-testid="couch"][data-row="15"][data-column-start="1"]');
    couch.click();
    return couch.getAttribute('data-state');
  })()`);
  console.log('couchClick', couchClick);
  await sleep(200);

  const afterSelect = await evalJs(`JSON.stringify({
    count: document.querySelector('[data-testid="selected-seats-count"]')?.textContent,
    rows: [...document.querySelectorAll('[data-testid="selected-seats-row"]')].map(r => ({row: r.getAttribute('data-row'), text: r.textContent})),
    continueDisabled: document.querySelector('[data-testid="continue-button"]')?.disabled,
  })`);
  console.log('afterSelect', afterSelect);
  const as = JSON.parse(afterSelect);
  check('selected count 3 (1 seat + couch=2)', as.count?.trim() === 'Selected seats: 3', as.count);
  check('row 7 line correct', as.rows.find((r) => r.row === '7')?.text.trim() === 'Row 7: 11', as.rows);
  check('row 15 line correct', as.rows.find((r) => r.row === '15')?.text.trim() === 'Row 15: 1-2', as.rows);
  check('continue enabled', as.continueDisabled === false, as.continueDisabled);

  // click continue -> summary
  await evalJs(`document.querySelector('[data-testid="continue-button"]').click()`);
  await waitFor(`location.pathname.endsWith('/summary')`);
  await sleep(300);
  const summaryInfo = await evalJs(`JSON.stringify({
    title: document.querySelector('[data-testid="summary-title"]')?.textContent,
    items: [...document.querySelectorAll('[data-testid="summary-item"]')].map(it => ({
      title: it.querySelector('[data-testid="summary-item-title"]').textContent,
      datetime: it.querySelector('[data-testid="summary-item-datetime"]').textContent,
      row: it.querySelector('[data-testid="summary-item-row"]').textContent,
      seat: it.querySelector('[data-testid="summary-item-seat"]').textContent,
      price: it.querySelector('[data-testid="summary-item-price"]').textContent,
    })),
    total: document.querySelector('[data-testid="summary-total"]')?.textContent,
  })`);
  console.log('summaryInfo', summaryInfo);
  const sum = JSON.parse(summaryInfo);
  check('summary has 2 items', sum.items.length === 2, sum.items);
  check('summary title', sum.title?.trim() === 'Your tickets');
  const seatItem = sum.items.find((i) => i.seat.trim() === '11');
  check('seat item row 7 price 32.00 PLN', seatItem?.price.trim() === '32.00 PLN', seatItem);
  const couchItem = sum.items.find((i) => i.seat.includes('Couch'));
  check('couch item desc Couch 1-2', couchItem?.seat.trim() === 'Couch 1-2', couchItem);
  check('couch price 89.00 PLN', couchItem?.price.trim() === '89.00 PLN', couchItem);
  check('total 121.00 PLN', sum.total?.trim() === 'Total: 121.00 PLN', sum.total);

  // Confirm -> checkout
  await evalJs(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await waitFor(`location.pathname.endsWith('/checkout')`);
  await sleep(300);

  // Click pay with empty form -> expect errors + toast
  const payLabel = await evalJs(`document.querySelector('[data-testid="pay-button"]')?.textContent`);
  console.log('payLabel', payLabel);
  check('pay label total', payLabel?.trim() === 'Pay 121.00 PLN', payLabel);

  await evalJs(`document.querySelector('[data-testid="pay-button"]').click()`);
