    emailError: document.querySelector('[data-testid="email-error"]')?.textContent,
    termsError: document.querySelector('[data-testid="terms-error"]')?.textContent,
    path: location.pathname,
  })`);
  console.log('invalidState', invalidState);
  const inv = JSON.parse(invalidState);
  check('toast shows form errors', inv.toast?.trim() === 'The form contains errors', inv.toast);
  check('first name required error', inv.firstNameError?.trim() === 'First name is required', inv.firstNameError);
  check('email required error', inv.emailError?.trim() === 'Email is required', inv.emailError);
  check('terms required error', inv.termsError?.trim() === 'You must accept the terms and conditions', inv.termsError);
  check('stayed on checkout', inv.path.endsWith('/checkout'), inv.path);

  // Fill valid form
  await evalJs(`(() => {
    function setVal(testid, val) {
      const el = document.querySelector('[data-testid="'+testid+'"]');
      const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      nativeInputValueSetter.call(el, val);
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('blur', { bubbles: true }));
    }
    setVal('first-name-input', 'Anna');
    setVal('last-name-input', 'Kowalska');
    setVal('email-input', 'anna@example.com');
    setVal('confirm-email-input', 'anna@example.com');
    setVal('phone-input', '123456789');
  })()`);
  await sleep(200);
  await evalJs(`(() => {
    const cb = document.querySelector('[data-testid="terms-checkbox"] input[type="checkbox"]') || document.querySelector('[data-testid="terms-checkbox"]');
    cb.click();
  })()`);
  await sleep(200);

  const filledState = await evalJs(`JSON.stringify({
    firstNameError: document.querySelector('[data-testid="first-name-error"]')?.textContent ?? null,
    emailError: document.querySelector('[data-testid="email-error"]')?.textContent ?? null,
    termsError: document.querySelector('[data-testid="terms-error"]')?.textContent ?? null,
  })`);
  console.log('filledState', filledState);

  await evalJs(`document.querySelector('[data-testid="pay-button"]').click()`);
  await waitFor(`location.pathname === '/confirmation'`, 8000);
  await sleep(300);
  const confirmInfo = await evalJs(`JSON.stringify({
    heading: document.querySelector('[data-testid="confirmation-heading"]')?.textContent,
    message: document.querySelector('[data-testid="confirmation-message"]')?.textContent,
  })`);
  console.log('confirmInfo', confirmInfo);
  const ci = JSON.parse(confirmInfo);
  check('confirmation heading', ci.heading?.trim() === 'Payment successful', ci.heading);
  check('confirmation message has email', ci.message?.includes('anna@example.com'), ci.message);

  // reload confirmation, should still show
  await navigate('http://localhost:4200/confirmation');
  await sleep(300);
  const afterReload = await evalJs(`JSON.stringify({ path: location.pathname, heading: document.querySelector('[data-testid="confirmation-heading"]')?.textContent })`);
  console.log('afterReload', afterReload);
  const ar = JSON.parse(afterReload);
  check('confirmation survives reload', ar.path === '/confirmation' && ar.heading?.trim() === 'Payment successful', ar);

  // Continue -> clears booking, goes to '/'
  await evalJs(`document.querySelector('[data-testid="confirmation-continue-button"]').click()`);
  await sleep(300);
  const afterContinue = await evalJs(`JSON.stringify({ path: location.pathname, bookingCleared: sessionStorage.getItem('cinescope:booking') === null })`);
  console.log('afterContinue', afterContinue);
  const ac = JSON.parse(afterContinue);
  check('continue navigates home', ac.path === '/', ac.path);
  check('booking cleared', ac.bookingCleared, ac.bookingCleared);

  // Try entering summary directly without booking -> redirect to /
  await navigate('http://localhost:4200/screenings/1/summary');
  await sleep(300);
  const guardCheck = await evalJs(`JSON.stringify({ path: location.pathname })`);
  console.log('guardCheck summary no booking', guardCheck);
  check('summary redirects without booking', JSON.parse(guardCheck).path === '/');

  await navigate('http://localhost:4200/confirmation');
  await sleep(300);
  const guardCheck2 = await evalJs(`JSON.stringify({ path: location.pathname })`);
  console.log('guardCheck confirmation unpaid', guardCheck2);
  check('confirmation redirects without paid booking', JSON.parse(guardCheck2).path === '/');

  // Unknown screening -> redirect to /
  await navigate('http://localhost:4200/screenings/9999/seats');
  await sleep(400);
  const unknownScreening = await evalJs(`JSON.stringify({ path: location.pathname })`);
  console.log('unknownScreening', unknownScreening);
  check('unknown screening redirects to /', JSON.parse(unknownScreening).path === '/');

  // Unknown route -> redirect to /
  await navigate('http://localhost:4200/this-does-not-exist');
  await sleep(300);
  const unknownRoute = await evalJs(`JSON.stringify({ path: location.pathname })`);
  check('unknown route redirects to /', JSON.parse(unknownRoute).path === '/', unknownRoute);

  console.log('DONE');
  process.exit(0);
}

run().catch((e) => {
  console.error('SCRIPT ERROR', e);
  process.exit(1);
});

