const WS_URL_BASE = 'http://127.0.0.1:9222';

async function main() {
  const versionInfo = await (await fetch(`${WS_URL_BASE}/json/version`)).json();
  const browserWs = new WebSocket(versionInfo.webSocketDebuggerUrl);
  await new Promise((resolve) => browserWs.addEventListener('open', resolve));

  let msgId = 0;
  const pending = new Map();
  browserWs.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  });

  function send(method, params = {}, sessionId) {
    const id = ++msgId;
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    browserWs.send(JSON.stringify(payload));
    return new Promise((resolve) => pending.set(id, resolve));
  }

  const { result: target } = await send('Target.createTarget', { url: 'about:blank' });
  const targetId = target.targetId;
  const { result: attach } = await send('Target.attachToTarget', { targetId, flatten: true });
  const sessionId = attach.sessionId;

  await send('Page.enable', {}, sessionId);
  await send('Runtime.enable', {}, sessionId);

  async function evalJs(expression, awaitPromise = true) {
    const resp = await send(
      'Runtime.evaluate',
      { expression, returnByValue: true, awaitPromise, userGesture: true },
      sessionId,
    );
    if (resp.result?.exceptionDetails) {
      throw new Error('EVAL ERROR: ' + JSON.stringify(resp.result.exceptionDetails));
    }
    return resp.result?.result?.value;
  }

  async function navigate(url) {
    await send('Page.navigate', { url }, sessionId);
    await sleep(600);
  }

  function sleep(ms) {
    return new Promise((r) => setTimeout(r, ms));
  }

  async function waitFor(expression, timeoutMs = 5000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      const ok = await evalJs(expression);
      if (ok) return true;
      await sleep(150);
    }
    throw new Error('waitFor timed out: ' + expression);
  }

  global.__cdp = { evalJs, navigate, sleep, waitFor, send, sessionId };
  return global.__cdp;
}

module.exports = main;

