async function main() {
  const versionInfo = await (await fetch('http://127.0.0.1:9222/json/version')).json();
  const browserWs = new WebSocket(versionInfo.webSocketDebuggerUrl);
  await new Promise((resolve) => browserWs.addEventListener('open', resolve));

  let msgId = 0;
  const pending = new Map();
  const consoleMsgs = [];
  browserWs.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
      return;
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      consoleMsgs.push('EXCEPTION: ' + JSON.stringify(msg.params.exceptionDetails));
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      consoleMsgs.push('CONSOLE[' + msg.params.type + ']: ' + msg.params.args.map((a) => a.value ?? a.description).join(' '));
    }
  });

  function send(method, params = {}, sessionId) {
    const id = ++msgId;
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    browserWs.send(JSON.stringify(payload));
    return new Promise((resolve) => pending.set(id, resolve));
  }

  const { result: target } = await send('Target.createTarget', { url: 'about:blank' });
  const targetId = target.targetId;
  const { result: attach } = await send('Target.attachToTarget', { targetId, flatten: true });
  const sessionId = attach.sessionId;

  await send('Page.enable', {}, sessionId);
  await send('Runtime.enable', {}, sessionId);

  const r1 = await send('Runtime.evaluate', { expression: '1+1', returnByValue: true }, sessionId);
  console.log('sanity eval before nav:', JSON.stringify(r1.result));

  await send('Page.navigate', { url: 'http://localhost:4200/' }, sessionId);
  await new Promise((r) => setTimeout(r, 2500));

  const r2 = await send('Runtime.evaluate', { expression: 'document.body.outerHTML', returnByValue: true }, sessionId);
  console.log('body after nav:', JSON.stringify(r2.result));

  console.log('--- console/exceptions ---');
  console.log(consoleMsgs.join('\n'));
  process.exit(0);
}

main().catch((e) => {
  console.error('ERR', e);
  process.exit(1);
});
EOF
